//! Micro-benchmark of a temporal LUT neuron on the Wio-E5.
//!
//! A LUT neuron reads k bits at fixed positions of the input history (64 channels x 64 ticks,
//! 128 `u32` words), forms a k-bit index and reads its output from a learned table of 2^k
//! entries. This binary measures, with synthetic connections and tables generated by `build.rs`:
//!
//! 1. k = 6, 1-bit outputs, group-sum readout, as straight-line code with constant bit
//!    positions (the compiler can use `UBFX` / `LSR` + `AND` with immediates);
//! 2. the same layer driven by an address table (positions loaded from Flash at run time);
//! 3. k = 8 with int8 table entries read with `LDRB`, summed into int32 class scores.
//!
//! Cycle counts come from DWT CYCCNT; inputs and outputs go through `black_box`.

#![no_std]
#![no_main]

#[path = "../board.rs"]
mod board;

// The generated code keeps a uniform `(bit) << i` pattern, including `<< 0`.
#[allow(clippy::identity_op)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/lut_generated.rs"));
}

use core::hint::black_box;
use cortex_m_rt::entry;
use generated::*;
use panic_halt as _;
use rtt_target::{rprintln, rtt_init_print, ChannelMode::BlockIfFull};

const ITER: u32 = 200;

#[inline(always)]
fn get_cycles() -> u32 {
    cortex_m::peripheral::DWT::cycle_count()
}

/// Same layer as `lut6_layer_codegen`, but bit positions and tables are read from Flash.
#[inline(never)]
fn lut6_layer_table(w: &[u32; LUT_WORDS], counts: &mut [u16; LUT_GROUPS]) {
    for (n, (addr, table)) in LUT6_ADDR.iter().zip(LUT6_TABLE.iter()).enumerate() {
        let mut i = 0u32;
        for (bit, [word, pos]) in addr.iter().enumerate() {
            i |= ((w[*word as usize] >> *pos) & 1) << bit;
        }
        counts[n % LUT_GROUPS] += ((table >> i) & 1) as u16;
    }
}

/// Runs `f` `ITER` times on `words` and returns the mean cycles per call.
fn measure<T: Copy + Default>(
    words: &[u32; LUT_WORDS],
    overhead: u32,
    mut f: impl FnMut(&[u32; LUT_WORDS], &mut T),
) -> (f32, T) {
    let mut out = T::default();
    let start = get_cycles();
    for _ in 0..ITER {
        let mut acc = T::default();
        f(black_box(words), &mut acc);
        out = black_box(acc);
    }
    let elapsed = get_cycles().wrapping_sub(start).saturating_sub(overhead);
    (elapsed as f32 / ITER as f32, out)
}

#[entry]
fn main() -> ! {
    rtt_init_print!(BlockIfFull, 4096);
    let mut cp = cortex_m::Peripherals::take().unwrap();
    cp.DCB.enable_trace();
    cp.DWT.enable_cycle_counter();

    rprintln!("\n================================================================================");
    rprintln!("TEMPORAL LUT NEURON MICRO-BENCHMARK: WIO-E5 (STM32WLE5JC)");
    rprintln!("================================================================================");
    let clock_hz = board::init_and_report();

    let t0 = get_cycles();
    let t1 = get_cycles();
    let overhead = t1.wrapping_sub(t0);

    // Synthetic input history with about 25 % of bits set (SHD-like density after binning).
    let mut words = [0u32; LUT_WORDS];
    let mut state = 0x1234_5678u32;
    for w in words.iter_mut() {
        for _ in 0..2 {
            state ^= state << 13;
            state ^= state >> 17;
            state ^= state << 5;
            *w |= state & (state >> 7) & 0x5555_5555 | (state & 0x0101_0101);
        }
    }
    let density = words.iter().map(|w| w.count_ones()).sum::<u32>() as f32 / 4096.0 * 100.0;
    rprintln!("Input: 4,096 history bits, {:.1}% set; {} iterations per measurement", density, ITER);

    let (c_gen, counts_gen) =
        measure::<[u16; LUT_GROUPS]>(&words, overhead, lut6_layer_codegen);
    let (c_tab, counts_tab) =
        measure::<[u16; LUT_GROUPS]>(&words, overhead, lut6_layer_table);
    let (c_k8, scores_k8) =
        measure::<[i32; LUT_GROUPS]>(&words, overhead, lut8_layer_codegen);

    let same = counts_gen == counts_tab;
    let total: u32 = counts_gen.iter().map(|&c| u32::from(c)).sum();

    rprintln!("\n1. k = 6, 1-bit output, group-sum, constant bit positions (generated code):");
    rprintln!(
        "   {} LUTs: {:.0} cycles per layer, {:.2} cycles per LUT ({:.2} us per layer)",
        LUT6_N,
        c_gen,
        c_gen / LUT6_N as f32,
        board::cycles_to_us(c_gen, clock_hz)
    );
    rprintln!("2. k = 6, same layer, bit positions read from an address table:");
    rprintln!(
        "   {} LUTs: {:.0} cycles per layer, {:.2} cycles per LUT ({:.2} us per layer)",
        LUT6_N,
        c_tab,
        c_tab / LUT6_N as f32,
        board::cycles_to_us(c_tab, clock_hz)
    );
    rprintln!(
        "   outputs identical to (1): {} ({} of {} LUTs output 1)",
        if same { "yes" } else { "NO" },
        total,
        LUT6_N
    );
    rprintln!("3. k = 8, int8 output read with LDRB, int32 class scores (generated code):");
    rprintln!(
        "   {} LUTs: {:.0} cycles per layer, {:.2} cycles per LUT (score[0] = {})",
        LUT8_N,
        c_k8,
        c_k8 / LUT8_N as f32,
        scores_k8[0]
    );
    rprintln!("\nSynthetic connections and tables; costs only, no accuracy. 1 run.");
    rprintln!("================================================================================\n");

    loop {
        cortex_m::asm::wfi();
    }
}
